function getParaulesClauTema(nomLectura){const n=(nomLectura||'').toLowerCase();if(n.includes('mascota'))return['gat','gata','gos','animal','mascota'];if(n.includes('menjar')||n.includes('cuinar'))return['poma','pa','pasta','sopa','menjar','cuina'];if(n.includes('roba'))return['roba','vestit','pantal','samarreta'];if(n.includes('escola')||n.includes('mestra')||n.includes('lectura'))return['llibre','escola','mestra','llegir','conte','classe'];if(n.includes('casa')||n.includes('ciutat'))return['casa','parc','botiga','ciutat','mercat'];if(n.includes('rutina')||n.includes('dia')||n.includes('setmana')||n.includes('hàbits'))return['hora','una','tres','cinc','set','matí','dia','setmana','córrer','llegir'];if(n.includes('amics')||n.includes('amistat')||n.includes('família'))return['content','contenta','amics','regal','família','mare','pare'];if(n.includes('esport')||n.includes('hobby'))return['futbol','bàsquet','tennis','partit','esport','juga'];if(n.includes('clima')||n.includes('medi'))return['sol','pluja','neu','vent','clima'];if(n.includes('música')||n.includes('aprendre'))return['so','cançó','estrella','cor','escolta','llegeix'];if(n.includes('tecnologia')||n.includes('joguines'))return['mòbil','càmera','llibre','joguina'];if(n.includes('viatjar'))return['cotxe','bici','tren','casa','ciutat','parc'];if(n.includes('futur')||n.includes('progrés')||n.includes('motivació')||n.includes('confiança'))return['llibre','mòbil','content','contenta','partit','trobat'];return[];}
function getTipEnllacatLectura(){if(!totsElsTips.length)return null;const idLectura=lecturaContext._plantillaId;if(idLectura!=null){const perId=totsElsTips.find(t=>t.id===idLectura);if(perId)return perId;}const claus=getParaulesClauTema(lecturaContext._plantillaNom||'');if(!claus.length)return null;const cands=totsElsTips.filter(t=>{const txt=((t.truc||'')+' '+((t.exemples||[]).join(' ')||t.exemple||'')).toLowerCase();return claus.some(c=>txt.includes(c));});if(!cands.length)return null;return cands[Math.floor(Math.random()*cands.length)];}
function getExemplesTip(tip){if(!tip)return[];if(Array.isArray(tip.exemples)&&tip.exemples.length)return tip.exemples;if(tip.exemple)return [tip.exemple,tip.exemple2,tip.exemple3].filter(Boolean);return[];}
let tipActual=null;
function pintarTipActual(){if(!tipActual)return;const t=document.getElementById('tip-text'); if(t)t.textContent=tipActual.truc||'';const exs=getExemplesTip(tipActual);const e1=document.getElementById('tip-exemple'); if(e1)e1.textContent=exs[0]?('1. '+exs[0]):'';const e2=document.getElementById('tip-exemple2'); if(e2)e2.textContent=exs[1]?('2. '+exs[1]):'';const e3=document.getElementById('tip-exemple3'); if(e3)e3.textContent=exs[2]?('3. '+exs[2]):'';const lec=document.getElementById('tip-lectura'); if(lec)lec.textContent=tipActual.lectura?('📖 '+tipActual.lectura):'';const badge=document.getElementById('tip-nivell'); if(badge){const niv=tipActual._nivell||getCurrentLevel();badge.textContent=niv.toUpperCase();badge.className='tip-badge '+niv;}}
function carregarTips(){let tots=[];if(dadesTips.a1) tots=tots.concat(dadesTips.a1.map(t=>({...t,_nivell:'a1'})));if(dadesTips.a2) tots=tots.concat(dadesTips.a2.map(t=>({...t,_nivell:'a2'})));if(dadesTips.b1) tots=tots.concat(dadesTips.b1.map(t=>({...t,_nivell:'b1'})));if(totsElsTips.length!==tots.length){totsElsTips=tots;tipsUsats=[];}mostrarTipRandom();}
function mostrarTipRandom(){if(!totsElsTips||totsElsTips.length===0){const el=document.getElementById('tip-text');if(el)el.textContent='No hi ha tips';return;}if(tipsUsats.length>=totsElsTips.length)tipsUsats=[];let idx; do{idx=Math.floor(Math.random()*totsElsTips.length);}while(tipsUsats.includes(idx));tipsUsats.push(idx);tipActual=totsElsTips[idx];pintarTipActual();vibrar();}
function getVerbsLectura(plantilla){if(plantilla.verbs&&plantilla.verbs.length)return plantilla.verbs;if(plantilla.vocab_ampliat&&plantilla.vocab_ampliat.verbs)return plantilla.vocab_ampliat.verbs.slice(0,6);return[];}
function contraure(text){return text.replace(/\bde el\b/g,'del').replace(/\bde els\b/g,'dels').replace(/\ba el\b/g,'al').replace(/\ba els\b/g,'als').replace(/\bha de ([aeiouàèéíòóú])/gi,"ha d'$1").replace(/\bhan de ([aeiouàèéíòóú])/gi,"han d'$1").replace(/\bde ([aeiouàèéíòóú])/gi,"d'$1");}
