let _temaMinijocForcat=null; function novaFraseMinijocTema(ids){_temaMinijocForcat=ids;novaFraseMinijoc();_temaMinijocForcat=null;}
function quitarSkinTone(e){return e?e.replace(/[\u{1F3FB}-\u{1F3FF}]/gu,''):'';}
function vibrar(){if(navigator.vibrate)navigator.vibrate(50);}
function mostrarMissatge(t){const d=document.createElement('div');d.textContent=t;d.style.cssText='position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#22c55e;color:#000;padding:12px 20px;border-radius:8px;font-weight:700;z-index:10000;';document.body.appendChild(d);setTimeout(()=>d.remove(),2000);}
function actualitzarUI(){const m=document.getElementById('monedes'),n=document.getElementById('nivell'),e=document.getElementById('energia'),b=document.getElementById('barra-progres'),h=document.getElementById('header-personatge');if(m)m.textContent=estat.monedes;if(n)n.textContent=estat.progres.nivellActualMapa;if(e)e.textContent=estat.progres.energia;if(b)b.style.width=((estat.progres.frasesDesDeUltimNivell/encertsNecessarisPerNivell(estat.progres.nivellActualMapa))*100)+'%';const p=PERSONATGES_JUGADOR.find(p=>p.id===estat.personatgeTriat);if(h&&p)h.textContent=p.emoji;}
function resetEnergiaDiaria(){const avui=new Date().toDateString();const ultimDia=localStorage.getItem('cat_ultim_dia_energia');if(ultimDia!==avui){estat.progres.energia=100;estat.ultimaRecargaEnergia=Date.now();localStorage.setItem('cat_ultim_dia_energia',avui);guardarEstat();}}
function guardarEstat(){localStorage.setItem('cat_monedes',estat.monedes);localStorage.setItem('cat_compres',JSON.stringify(estat.compres));localStorage.setItem('cat_nivell',estat.progres.nivellActualMapa);localStorage.setItem('cat_encerts',estat.progres.encerts);localStorage.setItem('cat_frasesContador',estat.progres.frasesDesDeUltimNivell);localStorage.setItem('cat_energia',estat.progres.energia);localStorage.setItem('cat_ultimaEnergia',estat.ultimaRecargaEnergia);localStorage.setItem('cat_intro',JSON.stringify(estat.introVist));localStorage.setItem('cat_desbloquejats',JSON.stringify(estat.desbloquejats));localStorage.setItem('cat_personatge',estat.personatgeTriat);localStorage.setItem('cat_xp',estat.progres.xp);localStorage.setItem('cat_ratxa',estat.progres.ratxa||0);}
function donarBonusDiari(){const avui=new Date().toDateString();const ultim=localStorage.getItem('cat_bonus_diari');if(ultim!==avui){estat.monedes+=10;localStorage.setItem('cat_bonus_diari',avui);guardarEstat();actualitzarUI();setTimeout(()=>mostrarMissatge('🎁 Bonus diari! +10 🪙 per tornar avui'),800);}}
function getCurrentLevel(){if(estat.progres.nivellActualMapa<=33)return'a1';if(estat.progres.nivellActualMapa<=66)return'a2';return'b1';}
function getGrupNivell(n){if(n<=33)return'A1';if(n<=66)return'A2';return'B1';}
function getColorNivell(n){if(n<=33)return'#22c55e';if(n<=66)return'#f59e0b';return'#3b82f6';}
function getFonsNivell(n){if(n<=33)return'rgba(34,197,94,0.15)';if(n<=66)return'rgba(245,158,11,0.15)';return'rgba(59,130,246,0.15)';}
function encertsNecessarisPerNivell(n){return 25+Math.floor((Math.max(1,n)-1)/10)*5;}
function recompensaPerPlantilla(pl){if(!pl)return 6;const id=(pl.id||'');if(id.startsWith('p7')||id.startsWith('p8'))return 15;if(id.startsWith('p4')||id.startsWith('p5'))return 10;if(id.startsWith('p1'))return 5;return 6;}
function getPlantillesDisponibles(){const nivell=estat.progres.nivellActualMapa||1;let llista=FRASES_MINIJOC.filter(p=>{const minMapa=p.minMapa||1;return minMapa<=nivell;});if(!llista.length)llista=FRASES_MINIJOC.filter(p=>(p.id||'').startsWith('p1'));if(!llista.length)llista=FRASES_MINIJOC;return llista;}
function gastarEnergia(c){if(c===0)return true;if(estat.progres.energia<c)return false;estat.progres.energia-=c;guardarEstat();actualitzarUI();return true;}
async function carregarDadesMinijoc(){try{const fr=await fetch('./data/minijoc_frases.json');if(fr.ok){const d=await fr.json();FRASES_MINIJOC=Array.isArray(d)?d:(d.frases||[]);}}catch(e){}if(!FRASES_MINIJOC.length){FRASES_MINIJOC=[{"id":"p1_1","text":"{persona} mira {objecte}","roles":{"persona":["persona"],"objecte":["objecte"]},"minMapa":1},{"id":"p1_2","text":"{persona} porta {roba}","roles":{"persona":["persona"],"roba":["roba"]},"minMapa":1},{"id":"p1_3","text":"{persona} va cap a {direccio}","roles":{"persona":["persona"],"direccio":["direccio"]},"minMapa":1},{"id":"p1_4","text":"Són {numero} {animal}","roles":{"numero":["numero"],"animal":["animal"]},"minMapa":1}];}minijocInicialitzat=true;}
async function carregarDades(){try{const r=await fetch('./data/categories_emoji.json');if(r.ok)CATEGORIES_TOTS=await r.json();}catch(e){}try{const r=await fetch('./data/biblioteca_emoji.json');if(r.ok)BIBLIOTECA_PLA=await r.json();}catch(e){}try{const r=await fetch('./data/botiga_emoji.json');if(r.ok)PACKS_BOTIGA=await r.json();}catch(e){}try{const r=await fetch('./data/banco_lectura.json');if(r.ok){BANCO_VOCAB=await r.json();BANCO_LECTURA=BANCO_VOCAB;}}catch(e){}try{const r=await fetch('./data/tips.json');if(r.ok)dadesTips=await r.json();}catch(e){}construirMapaDet();agruparBibliotecaPorCategoria();construirCategories();construirTotsEmojis();inicialitzarNomPersonatgeDefault();renderMapa();}
function construirMapaDet(){MAPA_DET={};for(const cat in CATEGORIES_TOTS){const arr=CATEGORIES_TOTS[cat]||[];arr.forEach(obj=>{if(!obj)return;const emoji=obj.emoji||obj;const base=quitarSkinTone(emoji);const det=obj.det||(cat==='roba'?'La':"El");const nom=obj.nom||obj.nom_cat||base;const genere=obj.genere||(cat==='roba'?'f':"m");if(!MAPA_DET[base]){MAPA_DET[base]={det,nom,genere,categoria:cat,emojiOriginal:emoji};}});}BIBLIOTECA_PLA.forEach(e=>{const base=quitarSkinTone(e.emoji);if(!MAPA_DET[base]){MAPA_DET[base]={det:"El",nom:e.nom_cat,genere:"m",categoria:e.categoria,emojiOriginal:e.emoji};}else{if(e.categoria)MAPA_DET[base].categoria=e.categoria;}});if(!MAPA_DET['🎵'])MAPA_DET['🎵']={det:'La',nom:'música',genere:'f',categoria:'musica',emojiOriginal:'🎵'};if(!MAPA_DET['❤️'])MAPA_DET['❤️']={det:'El',nom:'cor',genere:'m',categoria:'simbol',emojiOriginal:'❤️'};}
function inicialitzarNomPersonatgeDefault(){if(nomPersonatge)return;let llista=BANCO_LECTURA?.personatges;if(!llista||!llista.length)llista=["La Laia","En Pau","La Mercè","En Biel","L'Ona","En Roc"];const triat=llista[Math.floor(Math.random()*llista.length)];nomPersonatge=triat;localStorage.setItem('cat_nom_personatge',triat);}
function agruparBibliotecaPorCategoria(){BIBLIOTECA_POR_CAT={};BIBLIOTECA_PLA.forEach(e=>{if(!BIBLIOTECA_POR_CAT[e.categoria])BIBLIOTECA_POR_CAT[e.categoria]=[];BIBLIOTECA_POR_CAT[e.categoria].push(e);});}
function construirCategories(){const d=new Set(PACK_INICIAL.map(e=>quitarSkinTone(e)));estat.compres.forEach(id=>{const pId=id.includes('_p')?id.split('_p')[0]:id;const p=PACKS_BOTIGA.find(x=>x.id===pId||x.id===id);if(p&&p.emojis)p.emojis.forEach(e=>d.add(quitarSkinTone(e.emoji||e)));});CATEGORIES_DESBLOQUEJADES={};Object.keys(CATEGORIES_TOTS).forEach(c=>{const arr=CATEGORIES_TOTS[c]||[];const filtrats=arr.filter(obj=>{const emoji=obj.emoji||obj;return d.has(quitarSkinTone(emoji));}).map(obj=>(obj.emoji||obj));CATEGORIES_DESBLOQUEJADES[c]=filtrats;});estat.desbloquejats=CATEGORIES_DESBLOQUEJADES;}
function construirTotsEmojis(){TOTS_EMOJIS=BIBLIOTECA_PLA.map(e=>({...e}));}
document.addEventListener('DOMContentLoaded',async()=>{resetEnergiaDiaria();if(!estat.introVist){mostrarIntro();}else{const el=document.getElementById('intro');if(el)el.style.display='none';}await carregarDades();await carregarDadesMinijoc();actualitzarUI();donarBonusDiari();canviarTab('mapa',null);if(localStorage.getItem('cat_primera_lectura_feta')!=='1'){setTimeout(()=>generarLectura(),500);}});
function canviarTab(tab,e){document.querySelectorAll('.tab-content').forEach(t=>t.classList.remove('active'));document.querySelectorAll('.nav-item').forEach(b=>b.classList.remove('active'));document.getElementById('tab-'+tab)?.classList.add('active');if(e&&e.target)e.target.closest('.nav-item')?.classList.add('active');else document.querySelector(`.nav-item[onclick*="'${tab}'"]`)?.classList.add('active');if(tab==='mapa')renderMapa();if(tab==='missio')renderMissio();if(tab==='gremi')mostrarSubTab('biblioteca');if(tab==='lectura'){mostrarSubTab('lectura');}if(tab==='tips')carregarTips();if(tab==='botiga')renderBotiga();}
function forcarLecturaVisible(){const c=document.getElementById('lectura-texto');if(c){c.style.display='block';c.style.visibility='visible';c.style.opacity='1';}}
function mostrarSubTab(sub){const tabActiva=document.querySelector('.tab-content.active');if(!tabActiva)return;if(tabActiva.id==='tab-gremi'){tabActiva.classList.toggle('minijoc-actiu',sub==='minijoc');}tabActiva.querySelectorAll('.sub-tab-content').forEach(t=>t.style.display='none');document.querySelectorAll('.sub-tab-btn').forEach(b=>b.classList.remove('active'));const ids=[`lectura-${sub}`,`lectura-${sub}-inner`,`gremi-${sub}`,`lectura-${sub}-content`,`lectura-${sub}-texto`,`lectura-texto`,`gremi-${sub}-inner`,sub];let target=null;for(let id of ids){target=document.getElementById(id);if(target&&(tabActiva.contains(target)||sub==='lectura'))break;}if(!target){const todos=tabActiva.querySelectorAll('.sub-tab-content');if(sub==='lectura'&&todos[0])target=todos[0];if(sub==='vocab'&&todos[1])target=todos[1];if(sub==='gramatica'&&todos[2])target=todos[2];}if(target){target.style.display='block';const p=target.closest('.sub-tab-content');if(p)p.style.display='block';}document.querySelectorAll(`.sub-tab-btn[onclick*="'${sub}'"]`).forEach(b=>b.classList.add('active'));if(sub==='personatges')mostrarGremiPersonatges();if(sub==='biblioteca')renderDiccionari();if(sub==='minijoc'){if(!minijoc.fraseObjectiu) setTimeout(()=>novaFraseMinijoc(),100);}if(sub==='gramatica')setTimeout(()=>generarGramatica(),10);if(sub==='vocab')setTimeout(()=>renderVocabLectura(),10);if(sub==='lectura'){const c=document.getElementById('lectura-texto');if(c&&lecturaActualHTML&&!c.innerHTML.trim())c.innerHTML=lecturaActualHTML;if(c)c.style.display='block';forcarLecturaVisible();}}
function mostrarIntro(){const el=document.getElementById('intro');if(!el)return;if(estat.introVist){el.style.display='none';return;}el.style.display='flex';slideActual=0;pintarSlide();el.onclick=()=>seguentSlide();}
function pintarSlide(){const s=INTRO_SLIDES[slideActual];document.getElementById('intro-emoji').textContent=s.emoji;document.getElementById('intro-titol').textContent=s.titol;document.getElementById('intro-text').textContent=s.text;const d=document.getElementById('intro-dots');if(d)d.innerHTML=INTRO_SLIDES.map((_,i)=>`<span style="opacity:${i===slideActual?1:0.3}">●</span>`).join(' ');const b=document.getElementById('intro-btn');if(b){b.textContent=slideActual===INTRO_SLIDES.length-1?'Començar':'Següent';b.onclick=e=>{e.stopPropagation();seguentSlide();};}}
function seguentSlide(){vibrar();if(slideActual<INTRO_SLIDES.length-1){slideActual++;pintarSlide();}else saltarIntro();}
function saltarIntro(){estat.introVist=true;guardarEstat();document.getElementById('intro').style.display='none';}
function renderMapa(){const c=document.getElementById('mapa-contenidor');if(!c)return;if(!CATEGORIES_TOTS||Object.keys(CATEGORIES_TOTS).length===0){let h='<h3 style="text-align:center;margin-bottom:20px;">Carregant mapa...</h3><div class="nivells-grid">';for(let i=1;i<=100;i++)h+=`<div class="nivell-card" style="background:#222;border-color:#333;color:#555;opacity:0.5">${i}</div>`;c.innerHTML=h+'</div>';return;}let h='<h3 style="text-align:center;margin-bottom:12px;">Mapa de Nivells</h3><div style="display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin-bottom:16px;font-size:13px;font-weight:700;"><span style="background:rgba(34,197,94,0.15);border:1px solid #22c55e;color:#22c55e;padding:4px 10px;border-radius:20px;">🟢 A1 · 1-33</span><span style="background:rgba(245,158,11,0.15);border:1px solid #f59e0b;color:#f59e0b;padding:4px 10px;border-radius:20px;">🟠 A2 · 34-66</span><span style="background:rgba(59,130,246,0.15);border:1px solid #3b82f6;color:#3b82f6;padding:4px 10px;border-radius:20px;">🔵 B1 · 67-100</span></div><div class="nivells-grid">';for(let i=1;i<=100;i++){const d=i<=estat.progres.nivellActualMapa,o=d?'1':'0.4',cu=d?'pointer':'not-allowed',co=getColorNivell(i),bg=getFonsNivell(i),oc=d?`jugarNivell(${i})`:'';h+=`<div class="nivell-card" style="border-color:${co};background:${bg};opacity:${o};cursor:${cu};color:${d?co:'#888'}" onclick="${oc}">${i}<div style="font-size:10px;font-weight:700;opacity:0.9;">${getGrupNivell(i)}</div></div>`;}h+='</div>';c.innerHTML=h;}
function jugarNivell(n){if(n>estat.progres.nivellActualMapa)return;canviarTab('gremi',null);mostrarSubTab('minijoc');}
function renderMissio(){const c=document.getElementById('missio-contenidor');if(!c)return;const n=estat.progres.nivellActualMapa||1,necessaris=encertsNecessarisPerNivell(n),falten=Math.max(0,necessaris-(estat.progres.frasesDesDeUltimNivell||0));const pctNivell=necessaris?Math.round(((estat.progres.frasesDesDeUltimNivell||0)/necessaris)*100):0;const avui=new Date().toDateString();const bonusFet=localStorage.getItem('cat_bonus_diari')===avui;const ratxa=estat.progres.ratxa||0;const energia=estat.progres.energia;const packsTotal=PACKS_BOTIGA.length||44;const packsTens=estat.compres.length;const bibTotal=BIBLIOTECA_PLA.length||579;let bibDes=0;if(BIBLIOTECA_PLA.length){const base=PACK_INICIAL.map(e=>quitarSkinTone(e));BIBLIOTECA_PLA.forEach(e=>{const net=quitarSkinTone(e.emoji);const esBase=base.includes(net);const perPack=estat.compres.some(id=>{const pid=id.includes('_p')?id.split('_p')[0]:id;const pack=PACKS_BOTIGA.find(p=>p.id===pid||p.id===id);return pack&&pack.emojis.some(pe=>quitarSkinTone((pe.emoji||pe))===net);});if(esBase||perPack)bibDes++;});}const pctBib=bibTotal?Math.round((bibDes/bibTotal)*100):0;const fetesLlico=lecturaLlicoFetes();const esPrimera=localStorage.getItem('cat_primera_lectura_feta')!=='1';c.innerHTML=`<h3 style="text-align:center;margin-bottom:6px;">🎯 Missions</h3><p style="text-align:center;color:#aaa;font-size:13px;margin-bottom:16px;">Nivell ${n} · ${getGrupNivell(n)} · ${estat.monedes} 🪙 · ⚡ ${energia} · 🔥 Ratxa ${ratxa}/5</p><div class="missio-item" onclick="canviarTab('gremi',null);mostrarSubTab('minijoc');" style="cursor:pointer;"><div style="display:flex;justify-content:space-between;"><b>${falten>0?'🎯':'✅'} 1. Pujar de nivell</b><span style="color:#22c55e;font-weight:800;">${estat.progres.frasesDesDeUltimNivell||0}/${necessaris}</span></div><div style="font-size:13px;color:#aaa;margin-top:4px;">Et falten ${falten} encerts per pujar al Nivell ${n+1} · Minijoc 5-15 🪙 · Costa ${COST_MINIJOC} ⚡ per frase</div><div style="width:100%;height:6px;background:#333;border-radius:4px;margin-top:8px;"><div style="width:${Math.min(100,pctNivell)}%;height:100%;background:#22c55e;border-radius:4px;"></div></div></div><div class="missio-item" onclick="canviarTab('lectura',null);setTimeout(()=>mostrarSubTab('lectura'),100);" style="cursor:pointer;"><b>📚 2. Llegir una lectura</b><div style="font-size:13px;color:#aaa;margin-top:4px;">${esPrimera?'1ª Lectura GRATIS · Prova tot sense gastar':('Cost '+COST_LECTURA+' ⚡ · +5 🪙 per pregunta · +15 🪙 bonus si la completes · Cada dia 100 ⚡')}</div></div><div class="missio-item" onclick="canviarTab('lectura',null);setTimeout(()=>mostrarSubTab('gramatica'),100);" style="cursor:pointer;"><b>📝 3. Fer gramàtica</b><div style="font-size:13px;color:#aaa;margin-top:4px;">+3 🪙 per quiz · +10 🪙 bonus si fas 3/3 · ${gramaticaCorrectes||0}/${gramaticaTotalQuiz||3} en aquesta lliçó ${lecturaProgres.gramatica?'· ✅ Feta':''}</div></div><div class="missio-item" onclick="canviarTab('gremi',null);mostrarSubTab('minijoc');" style="cursor:pointer;"><b>🔥 4. Ratxa de 5</b><div style="font-size:13px;color:#aaa;margin-top:4px;">Portes ${ratxa}/5 · Si arribes a 5, +10 🪙 bonus i la ratxa es reinicia</div></div><div class="missio-item" style="cursor:${bonusFet?'default':'pointer'};" onclick="if(!${bonusFet})donarBonusDiari();"><b>${bonusFet?'✅':'🎁'} 5. Bonus diari</b><div style="font-size:13px;color:#aaa;margin-top:4px;">${bonusFet?'Ja l\'has agafat avui · Torna demà per +10 🪙':'Entra cada dia i emporta\'t +10 🪙'}</div></div><div class="missio-item" onclick="canviarTab('botiga',null);" style="cursor:pointer;"><b>📦 6. Desbloqueja un pack</b><div style="font-size:13px;color:#aaa;margin-top:4px;">Tens ${packsTens}/${packsTotal} packs · Biblioteca ${bibDes}/${bibTotal} (${pctBib}%)</div><div style="width:100%;height:6px;background:#333;border-radius:4px;margin-top:8px;"><div style="width:${pctBib}%;height:100%;background:#f59e0b;border-radius:4px;"></div></div></div><div class="missio-item" onclick="canviarTab('lectura',null);setTimeout(()=>mostrarSubTab('lectura'),100);" style="cursor:pointer;"><b>${lecturaLlicoCompleta()?'✅':'🔒'} 7. Completar la lliçó completa</b><div style="font-size:13px;color:#aaa;margin-top:4px;">Lliçó actual: ${fetesLlico}/4 · ${lecturaProgres.preguntes?'✅ Lectura ': '⬜ Lectura '}· ${lecturaProgres.vocab?'✅ Vocab ': '⬜ Vocab '}· ${lecturaProgres.gramatica?'✅ Gramàtica ': '⬜ Gramàtica '}· ${lecturaProgres.minijoc?'✅ Mini-joc':'⬜ Mini-joc'}</div></div><div class="missio-item" onclick="recarregarEnergia()" style="cursor:pointer;"><b>⚡ 8. Energia al màxim</b><div style="font-size:13px;color:#aaa;margin-top:4px;">Energia: ${energia}/100 · Cada dia 100 ⚡ · Recarrega per 50 🪙 ${energia>=100?'(ja la tens al màxim)':''}</div></div>`;}
function recarregarEnergia(){if(estat.progres.energia>=100){mostrarMissatge('Ja tens l\'energia al màxim!');return;}if(estat.monedes<50){mostrarMissatge('Necessites 50 monedes');return;}estat.monedes-=50;estat.progres.energia=100;estat.ultimaRecargaEnergia=Date.now();guardarEstat();actualitzarUI();renderMissio();vibrar();mostrarMissatge('Energia recarregada!');}
function mostrarGremiPersonatges(){const c=document.getElementById('gremi-personatges');if(!c)return;let h=`<div style="text-align:center;padding:20px;"><div style="font-size:80px;">${PERSONATGES_JUGADOR.find(p=>p.id===estat.personatgeTriat).emoji}</div><h3>Avatar: ${PERSONATGES_JUGADOR.find(p=>p.id===estat.personatgeTriat).nom}</h3><p style="color:#22c55e;">Protagonista de les lectures: <b>${nomPersonatge||'aleatori'}</b></p><p style="font-size:12px;color:#aaa;">Tria el teu avatar. El protagonista de les lectures és un personatge de la història, no el teu avatar.</p><div style="border-top:1px solid #333;padding-top:20px;"><h4>Canvia avatar</h4><div class="emoji-grid">`;PERSONATGES_JUGADOR.forEach(x=>{const s=x.id===estat.personatgeTriat;h+=`<div class="emoji-item" style="border:${s?'2px solid #22c55e':'1px solid #333'};cursor:pointer;" onclick="triarPersonatge('${x.id}')"><div class="emoji-large">${x.emoji}</div><div class="emoji-name">${x.nom}</div></div>`;});h+=`</div></div></div>`;c.innerHTML=h;}
function triarPersonatge(id){estat.personatgeTriat=id;guardarEstat();actualitzarUI();mostrarGremiPersonatges();vibrar();}
function renderDiccionari(){const c=document.getElementById('gremi-biblioteca');if(!c)return;const q=(filtreBiblioteca||'').toLowerCase().trim();let total=0,desbloquejats=0;BIBLIOTECA_PLA.forEach(e=>{const net=quitarSkinTone(e.emoji);const esBase=PACK_INICIAL.some(p=>quitarSkinTone(p)===net);const perPack=estat.compres.some(id=>{const pid=id.includes('_p')?id.split('_p')[0]:id;const pack=PACKS_BOTIGA.find(p=>p.id===pid||p.id===id);return pack&&pack.emojis.some(pe=>quitarSkinTone((pe.emoji||pe))===net);});total++;if(esBase||perPack)desbloquejats++;});const pct=total?Math.round((desbloquejats/total)*100):0;let h=`<h3 style="text-align:center;">📚 Biblioteca</h3><p style="text-align:center;color:#aaa;font-size:13px;">${desbloquejats} de ${total} desbloquejats · ${pct}%</p><div style="width:100%;height:8px;background:#333;border-radius:4px;margin:8px 0 14px;"><div style="width:${pct}%;height:100%;background:#22c55e;border-radius:4px;"></div></div><input id="cerca-biblioteca" type="text" placeholder="🔍 Busca: gos, poma, bandera, cotxe..." value="${filtreBiblioteca.replace(/"/g,'')}" oninput="filtreBiblioteca=this.value;renderDiccionari();" style="width:100%;padding:12px;border-radius:12px;border:1px solid #333;background:#121212;color:#fff;font-size:15px;margin-bottom:6px;outline:none;"><div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px;"><button class="btn btn-sec" style="margin:0;padding:6px 12px;font-size:12px;" onclick="filtreBiblioteca='';renderDiccionari();">Tot</button><button class="btn btn-sec" style="margin:0;padding:6px 12px;font-size:12px;" onclick="filtreBiblioteca='gos';renderDiccionari();">🐶 Animals</button><button class="btn btn-sec" style="margin:0;padding:6px 12px;font-size:12px;" onclick="filtreBiblioteca='poma';renderDiccionari();">🍎 Menjar</button><button class="btn btn-sec" style="margin:0;padding:6px 12px;font-size:12px;" onclick="filtreBiblioteca='bandera';renderDiccionari();">🌍 Banderes</button><button class="btn btn-sec" style="margin:0;padding:6px 12px;font-size:12px;" onclick="filtreBiblioteca='casa';renderDiccionari();">🏠 Casa</button></div>`;const base=PACK_INICIAL.map(e=>quitarSkinTone(e));let trobat=false;for(const[cat,emojis]of Object.entries(BIBLIOTECA_POR_CAT)){const filtrats=emojis.filter(e=>{if(!q)return true;return (e.nom_cat||'').toLowerCase().includes(q)||(e.categoria||'').toLowerCase().includes(q)||(e.para_frases||[]).join(' ').toLowerCase().includes(q)||cat.toLowerCase().includes(q);});if(!filtrats.length)continue;trobat=true;h+=`<h4 style="margin:20px 0 8px;color:#4CAF50;text-transform:capitalize;">${cat} (${filtrats.length})</h4><div class="emoji-grid">`;filtrats.forEach(e=>{const net=quitarSkinTone(e.emoji),esBase=base.includes(net),perPack=estat.compres.some(id=>{const pid=id.includes('_p')?id.split('_p')[0]:id;const pack=PACKS_BOTIGA.find(p=>p.id===pid||p.id===id);return pack&&pack.emojis.some(pe=>quitarSkinTone((pe.emoji||pe))===net);}),des=esBase||perPack;h+=`<div class="emoji-item" style="opacity:${des?'1':'0.35'};filter:${des?'':'grayscale(1)'};"><div class="emoji-large">${e.emoji}</div><div class="emoji-name">${e.nom_cat}</div></div>`;});h+=`</div>`;}if(!trobat){h+=`<div style="text-align:center;padding:30px;opacity:.6;">No hi ha resultats per "<b>${filtreBiblioteca}</b>"<br><button class="btn btn-sec" onclick="filtreBiblioteca='';renderDiccionari();">Veure tot</button></div>`;}c.innerHTML=h;const input=document.getElementById('cerca-biblioteca');if(input&&q){input.focus();input.setSelectionRange(input.value.length,input.value.length);}}
function haDeSerApostrof(nom){if(!nom)return false;const n=nom.toLowerCase().trim();if(/^[aeiouàèéíòóú]/.test(n))return true;if(/^h[aeiouàèéíòóú]/.test(n))return true;return false;}
function obtenirArticleNet(emoji){const base=quitarSkinTone(emoji);const info=MAPA_DET[base];if(!info)return emoji;if(CATS_SENSE_ARTICLE.has(info.categoria))return info.nom;let det=info.det;let nom=info.nom;if(det==="En"||det==="Na"){if(nom.toLowerCase()==="home")return "L'"+nom;if(nom.toLowerCase()==="dona")return "La "+nom;if(haDeSerApostrof(nom))return "L'"+nom;if(det==="En")return "El "+nom;return "La "+nom;}if(haDeSerApostrof(nom))return "L'"+nom;if(det==="El")return "El "+nom;if(det==="La")return "La "+nom;if(det==="L'")return "L'"+nom;return det+" "+nom;}
function obtenirNomSenseArticle(emoji){const b=quitarSkinTone(emoji);const i=MAPA_DET[b];return i?i.nom:emoji;}
function flexionarEmocio(nom,genere,plural){nom=(nom||'').toLowerCase();if(nom==='riure')return 'rient';if(nom==='somriure')return 'somrient';if(nom==='feliç')return plural?(genere==='f'?'felices':'feliços'):'feliç';if(nom==='content')return plural?(genere==='f'?'contentes':'contents'):(genere==='f'?'contenta':'content');if(nom==='trist')return plural?(genere==='f'?'tristes':'trists'):(genere==='f'?'trista':'trist');if(nom==='enfadat')return plural?(genere==='f'?'enfadades':'enfadats'):(genere==='f'?'enfadada':'enfadat');if(nom==='enamorat')return plural?(genere==='f'?'enamorades':'enamorats'):(genere==='f'?'enamorada':'enamorat');return nom;}
function formatDireccio(elegido){const info=MAPA_DET[quitarSkinTone(elegido)];if(!info)return obtenirNomSenseArticle(elegido);const nom=info.nom;if(nom==='dreta')return 'a la dreta';if(nom==='esquerra')return "a l'esquerra";return nom;}
function netejarFraseFinal(text){text=text.replace(/En home/g,"L'home").replace(/Na dona/g,'La dona');text=text.replace(/\bEl (h[aeiouàèéíòóú][a-zàèéíòóú]+)/gi,"L'$1");text=text.replace(/\bLa (h[aeiouàèéíòóú][a-zàèéíòóú]+)/gi,"L'$1");text=text.replace(/\bEl ([aeiouàèéíòóú][a-zàèéíòóú]+)/gi,"L'$1");text=text.replace(/\bLa ([aeiouàèéíòóú][a-zàèéíòóú]+)/gi,"L'$1");text=text.replace(/\bFa floc de neu\b/gi,'Fa neu');text=text.replace(/\bfa floc de neu\b/g,'fa neu');text=text.replace(/^Són la una\b/,'És la una').replace(/^Són la una i/,'És la una i');text=text.replace(/\bnúmero un\b/g,'número u');const parts=text.split(' ');if(parts.length>1){const cap=parts[0];let cua=parts.slice(1).join(' ');cua=cua.replace(/\bEl\b/g,'el').replace(/\bLa\b/g,'la').replace(/\bEls\b/g,'els').replace(/\bLes\b/g,'les').replace(/\bL'/g,"l'").replace(/\bEn\b/g,'en');cua=cua.replace(/\ba el\b/g,'al').replace(/\bde el\b/g,'del');cua=cua.replace(/\ba els\b/g,'als').replace(/\bde els\b/g,'dels');text=cap+' '+cua;}text=contraure(text);text=text.replace(/ +/g,' ').trim();if(text.length>0)text=text.charAt(0).toUpperCase()+text.slice(1);text=text.replace(/\{[^}]+\}/g,'').replace(/ +/g,' ').trim();return text;}
function generarFraseDinamicaLogica(pl,jug){let text=pl.text;let sol=[];let usats=new Set();let claus=pl.roles?Object.keys(pl.roles):[];let generesPersones=[];let esPluralEmocio=false;if(pl.roles&&(pl.roles.persona_2||(pl.text||'').includes('{persona_2}')))esPluralEmocio=true;if(pl.id==='p7_1')esPluralEmocio=false;for(const rol of claus){const baseKey=rol.split('_')[0];const cats=pl.roles?pl.roles[rol]:[baseKey];let pool=[];cats.forEach(cat=>{const desbloquejats=(CATEGORIES_DESBLOQUEJADES[cat]||[]);const font=desbloquejats.length?desbloquejats:(CATEGORIES_TOTS[cat]||[]);font.forEach(o=>{const em=o.emoji||o;const base=quitarSkinTone(em);if(!usats.has(base))pool.push(em);});(BIBLIOTECA_POR_CAT[cat]||[]).forEach(e=>{const base=quitarSkinTone(e.emoji);if(!usats.has(base)){if(!pool.some(p=>quitarSkinTone(p)===base))pool.push(e.emoji);}});});if(pool.length===0){text=text.replaceAll('{'+rol+'}','');continue;}const elegido=pool[Math.floor(Math.random()*pool.length)];usats.add(quitarSkinTone(elegido));const infoElegido=MAPA_DET[quitarSkinTone(elegido)];const categoriaElegida=infoElegido?infoElegido.categoria:baseKey;if((rol==='persona'||rol==='persona_2')&&infoElegido)generesPersones.push(infoElegido.genere||'m');if(categoriaElegida==='emocio'){let genereEmocio='m';if(pl.id==='p7_1'){genereEmocio=generesPersones.length?generesPersones[generesPersones.length-1]:'m';}else if(generesPersones.length){genereEmocio=generesPersones.every(g=>g==='f')?'f':'m';}const flex=flexionarEmocio(obtenirNomSenseArticle(elegido),genereEmocio,esPluralEmocio);text=text.replaceAll('{'+rol+'}',flex);sol.push(elegido);continue;}let esSenseArticle=infoElegido&&CATS_SENSE_ARTICLE.has(infoElegido.categoria);let reemplazo=esSenseArticle?obtenirNomSenseArticle(elegido):obtenirArticleNet(elegido);if(categoriaElegida==='clima'){const nomClima=obtenirNomSenseArticle(elegido).toLowerCase();if(nomClima==='floc de neu'){text=text.replace('Fa {'+rol+'}','Fa neu');sol.push(elegido);continue;}}if(categoriaElegida==='numero'){const nomNum=obtenirNomSenseArticle(elegido);const nomNumNet=(nomNum==='un')?'u':nomNum;if(text.includes('número {'+rol+'}')){text=text.replaceAll('número {'+rol+'}','número '+nomNumNet);sol.push(elegido);continue;}if(text.includes('Són {'+rol+'}')){text=text.replace('Són {'+rol+'}','És un');sol.push(elegido);continue;}}if(categoriaElegida==='direccio'){const dir=formatDireccio(elegido);text=text.replaceAll('{'+rol+'}',dir);sol.push(elegido);continue;}if(text.includes('a {'+rol+'}')){if(!esSenseArticle){if(reemplazo.startsWith('El '))reemplazo='el '+obtenirNomSenseArticle(elegido);if(reemplazo.startsWith("L'"))reemplazo="l'"+obtenirNomSenseArticle(elegido);if(reemplazo.startsWith('La '))reemplazo='la '+obtenirNomSenseArticle(elegido);}text=text.replace('a {'+rol+'}','a '+reemplazo);}else{text=text.replaceAll('{'+rol+'}',reemplazo);}sol.push(elegido);}text=netejarFraseFinal(text);return{text,solucio:sol};}
let _ultimaPlantillaMinijoc=null;
function desferUltimEmoji(){if(!minijoc.fraseObjectiu)return;if(!minijoc.emojisTriats.length)return;vibrar();const idx=minijoc.emojisTriatsIdx.pop();minijoc.emojisTriats.pop();if(idx!==undefined){const grid=document.getElementById('minijoc-emojis');const card=grid?.children[idx];if(card)card.classList.remove('seleccionat');}actualitzarTriatsMinijoc();}
function actualitzarTriatsMinijoc(){const el=document.getElementById('minijoc-triats');const cont=document.getElementById('gremi-minijoc');const inst=document.getElementById('minijoc-instruccio');const btnDesfer=document.getElementById('minijoc-desfer');if(!el||!minijoc.fraseObjectiu)return;const total=minijoc.fraseObjectiu.solucio.length;const fets=minijoc.emojisTriats.length;const parts=[];for(let i=0;i<total;i++){parts.push(i<fets?minijoc.emojisTriats[i]:'○');}const complet=fets===total;el.textContent=parts.join(' ')+'  ·  '+fets+'/'+total+(complet?' ✅':'');el.classList.toggle('llarg',total>=4);el.classList.toggle('complet',complet);if(inst){inst.textContent='👆 Toca els emojis en ordre per completar la frase';inst.classList.remove('complet');inst.style.display=complet?'none':'block';}if(btnDesfer)btnDesfer.disabled=fets===0;if(cont){cont.classList.toggle('minijoc-llarg',total===4);cont.classList.toggle('minijoc-molt-llarg',total>=5);}}
function novaFraseMinijoc(){const fraseEl=document.getElementById('minijoc-frase');const feedbackEl=document.getElementById('minijoc-feedback');const nivellEl=document.getElementById('minijoc-nivell');if(fraseEl&&!FRASES_MINIJOC.length){fraseEl.textContent="Carregant frases...";carregarDadesMinijoc().then(()=>novaFraseMinijoc());return;}if(!minijocInicialitzat){if(fraseEl)fraseEl.textContent="Carregant...";setTimeout(()=>novaFraseMinijoc(),300);return;}if(!gastarEnergia(COST_MINIJOC)){if(fraseEl)fraseEl.textContent="Sense energia! Espera o recarrega a Missions.";mostrarMissatge('Sense energia!');return;}const emojisUsables=BIBLIOTECA_PLA.length>0?BIBLIOTECA_PLA.map(e=>e.emoji):PACK_INICIAL;let disponibles=getPlantillesDisponibles();if(_temaMinijocForcat&&_temaMinijocForcat.length){const filtrades=disponibles.filter(p=>_temaMinijocForcat.includes(p.id));if(filtrades.length)disponibles=filtrades;}let candidates=disponibles.filter(p=>p.id!==_ultimaPlantillaMinijoc);if(!candidates.length)candidates=disponibles;const pl=candidates[Math.floor(Math.random()*candidates.length)];_ultimaPlantillaMinijoc=pl.id;const{text,solucio}=generarFraseDinamicaLogica(pl,emojisUsables);minijoc.fraseObjectiu={text,solucio};minijoc.plantillaActual=pl;minijoc.emojisTriats=[];minijoc.emojisTriatsIdx=[];if(fraseEl)fraseEl.textContent=text;if(feedbackEl)feedbackEl.innerHTML='';if(nivellEl)nivellEl.textContent=`Nivell ${estat.progres.nivellActualMapa} · ${getGrupNivell(estat.progres.nivellActualMapa)} · ${solucio.length} emojis · 🔥 ${estat.progres.ratxa||0}/5 · Falten ${Math.max(0,encertsNecessarisPerNivell(estat.progres.nivellActualMapa)-(estat.progres.frasesDesDeUltimNivell||0))}`;actualitzarTriatsMinijoc();generarOpcionsMinijoc(solucio);}
function generarOpcionsMinijoc(solucio){const grid=document.getElementById('minijoc-emojis');if(!grid)return;const num=solucio.length<=3?10:(solucio.length===4?12:14);const numF=num-solucio.length;let baseTot=BIBLIOTECA_PLA.map(e=>e.emoji);['🎵','❤️'].forEach(e=>{if(!baseTot.some(x=>quitarSkinTone(x)===quitarSkinTone(e)))baseTot.push(e);});if(baseTot.length===0)baseTot=PACK_INICIAL;const vistos=new Set();baseTot=baseTot.filter(e=>{const b=quitarSkinTone(e);if(vistos.has(b))return false;vistos.add(b);return true;});const solBases=new Set(solucio.map(s=>quitarSkinTone(s)));const falsos=baseTot.filter(e=>!solBases.has(quitarSkinTone(e))).sort(()=>0.5-Math.random()).slice(0,numF);const opcions=[...solucio,...falsos];const vistos2=new Set();const opcionsNetes=opcions.filter(e=>{const b=quitarSkinTone(e);if(vistos2.has(b))return false;vistos2.add(b);return true;});const opcionsFinal=opcionsNetes.sort(()=>0.5-Math.random());minijoc.emojisDisponibles=opcionsFinal;grid.innerHTML='';opcionsFinal.forEach((emoji,i)=>{const ed=BIBLIOTECA_PLA.find(e=>quitarSkinTone(e.emoji)===quitarSkinTone(emoji));const info=MAPA_DET[quitarSkinTone(emoji)];const nomMostrar=ed?.nom_cat||info?.nom||'';const div=document.createElement('div');div.className='emoji-item';div.innerHTML=`<div class="emoji-large">${emoji}</div><div class="emoji-name">${nomMostrar}</div>`;div.onclick=()=>triarEmojiMinijoc(i,div);grid.appendChild(div);});}
function triarEmojiMinijoc(idx,elDiv){vibrar();if(!minijoc.fraseObjectiu)return;const emoji=minijoc.emojisDisponibles[idx],max=minijoc.fraseObjectiu.solucio.length;if(!emoji)return;if(minijoc.emojisTriatsIdx.includes(idx))return;const base=quitarSkinTone(emoji);if(minijoc.emojisTriats.some(e=>quitarSkinTone(e)===base))return;if(minijoc.emojisTriats.length<max){minijoc.emojisTriats.push(emoji);minijoc.emojisTriatsIdx.push(idx);if(elDiv)elDiv.classList.add('seleccionat');actualitzarTriatsMinijoc();if(minijoc.emojisTriats.length===max)setTimeout(comprovarMinijoc,300);}}
