async function cargarBancoLectura(){if(BANCO_LECTURA&&BANCO_LECTURA.a1&&BANCO_LECTURA.a1.plantillas)return BANCO_LECTURA;try{const r=await fetch('./data/banco_lectura.json');if(!r.ok)throw new Error('HTTP '+r.status);const j=await r.json();BANCO_LECTURA=j;}catch(e){const el=document.getElementById('lectura-texto');if(el){el.style.display='block';el.innerHTML=`<div style="padding:20px;background:#3f1d1d;border:1px solid #f44336;border-radius:8px;"><h3>⚠️ No puedo leer banco_lectura.json</h3><p>${e.message}</p><button class="btn btn-primari" onclick="generarLectura()">🔄 Reintentar</button></div>`;forcarLecturaVisible();}return null;}if(!nomPersonatge)inicialitzarNomPersonatgeDefault();return BANCO_LECTURA;}
let _ultimaPlantillaId=null; function _barrejar(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;} function _reemplaLectura(t,pers,pronom){if(!t)return"";return t.replace(/\$\{(\w+)\}/g,(m,k)=>{if(k==='personatge')return pers;if(k==='pronom')return pronom;return k;});}
